code_example:
namespace Core {
    int counter = 0;
    void log() {}
}

// 1. Qualified access
int c1 = Core::counter;

// 2. Using Declaration (for a single name)
using Core::log;
log();

// 3. Using Directive (for all names)
using namespace Core;
counter = 10;

// Warning: Can lead to conflicts
namespace External {
    int counter = 99;
    // Core::counter still required here
}
